const button = document.querySelector(".btn");
const counter = document.querySelector(".count");
let count = 0;

button.addEventListener("click", function () {
  count = count + 1;
  counter.textContent = "Clicks: " + count;
});

const subBtn = document.querySelector(".sub-btn");

subBtn.addEventListener("click", function () {
  subBtn.classList.toggle("subscribed");

  if (subBtn.classList.contains("subscribed")) {
    subBtn.textContent = "Subscribed";
  } else {
    subBtn.textContent = "Subscribe";
  }
});

const input = document.querySelector(".name");
const hello = document.querySelector(".hello");

input.addEventListener("input", function () {
  hello.textContent = input.value;
});

const face = document.querySelector(".face");

face.addEventListener("mouseover", function () {
  face.textContent = "😃";
});

face.addEventListener("mouseout", function () {
  face.textContent = "😐";
});

const buttons = document.querySelectorAll(".colors button");

buttons.forEach(function (btn) {
  btn.addEventListener("click", function (e) {
    document.body.style.backgroundColor = e.target.textContent;
  });
});

input.addEventListener("input", function () {
  const name = input.value;
  if (name === "") {
    cardName.textContent = "Your name";
    avatar.textContent = "?";
  } else {
    cardName.textContent = name;
    avatar.textContent = name[0].toUpperCase();
  }
});

likeBtn.addEventListener("click", function () {
  likeBtn.classList.toggle("liked");
  if (likeBtn.classList.contains("liked")) {
    likes = likes + 1;
    likeBtn.textContent = `❤️ ${likes}`;
  } else {
    likes = likes - 1;
    likeBtn.textContent = `🤍 ${likes}`;
  }
});

